 const originals=new WeakMap();
 function scan(){const lang=menu.value;document.querySelectorAll(selector).forEach(el=>{let src=originals.get(el);if(!src){src=el.textContent.trim();if(!src)return;originals.set(el,src)}const link=el.closest('.catalog-card,.detail-related-card,.product-card')?.querySelector('a[href*="/product/"]')||el.closest('a[href*="/product/"]');let id=link?new URL(link.href,location.href).searchParams.get('id'):null;if(!id&&el.matches('.detail-info h1'))id=new URLSearchParams(location.search).get('id');const entry=productIdTitles[id];const value=lang==='en'?src:((entry?.name===src&&entry.translations[lang])||localTitles[lang]?.[src]||src);if(el.textContent!==value)el.textContent=value;const card=el.closest('.product-card,.catalog-card,.detail-related-card,.detail-layout');const img=card&&card.querySelector('img');if(img&&img.getAttribute('alt')!==value)img.setAttribute('alt',value)});const detailTitle=document.querySelector('.detail-info h1');const detailSource=detailTitle&&originals.get(detailTitle);if(detailSource){const detailValue=detailTitle.textContent;document.querySelectorAll('.detail-weidian-grid img').forEach((img,index)=>{const alt=detailValue+' '+(index+1);if(img.getAttribute('alt')!==alt)img.setAttribute('alt',alt)})}}
 let scheduled=false;function schedule(){if(scheduled)return;scheduled=true;setTimeout(()=>{scheduled=false;scan()},0)}
 menu.addEventListener('change',scan);new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true});scan();
